/**
 * Node-RED Function: Extract disk USED percent from `df -h` output
 *
 * Input:
 *   msg.payload = full text output of `df -h`
 *
 * Output:
 *   msg.payload = <number>   // percent used (e.g., 64)
 *
 * Default behavior:
 *   - returns Use% for the root filesystem mounted on "/"
 *
 * Notes:
 *   - Handles 1–3 digit percentages (0%..100%)
 *   - Avoids accidentally grabbing the first 2-digit percent from some other mount
 */

const text = (msg.payload ?? "").toString();
const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

// Choose which mount you want; "/" is most common.
const TARGET_MOUNT = "/";

for (const line of lines) {
    // Match lines that end with the mount point (e.g., "... 64% /")
    // Use whitespace before mount to avoid matching "/boot/firmware" when TARGET_MOUNT is "/"
    const mountRe = new RegExp(`\\s${TARGET_MOUNT.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}$`);
    if (!mountRe.test(line)) continue;

    // Extract Use% (first occurrence of N% on that line)
    const m = line.match(/(\d{1,3})%/);
    if (m) {
        msg.payload = Number(m[1]); // disk USED percent
        return msg;
    }
}

// If we didn't find the target mount, fall back to first percentage found (optional)
// Comment out this block if you'd rather output null on failure.
const fallback = text.match(/(\d{1,3})%/);
if (fallback) {
    msg.payload = Number(fallback[1]);
    return msg;
}

msg.payload = null;
return msg;

