/**
 * Node-RED Function: Extract first two IPv4 addresses from a string
 *
 * Input:
 *   msg.payload (string) e.g.
 *   "192.168.70.116 100.79.140.14 fd54:... fd7a:..."
 *
 * Output:
 *   msg.payload = {
 *     ipv4_1: "192.168.70.116",
 *     ipv4_2: "100.79.140.14"
 *   }
 *
 * Notes:
 * - Uses an IPv4 regex where each octet is 1–3 digits (as requested).
 * - Discards the rest (IPv6, etc.).
 * - If fewer than 2 IPv4s are found, missing fields are omitted.
 */

// Ensure we have a string to parse
const s = (msg.payload ?? "").toString();

// IPv4 pattern: 4 groups of 1–3 digits separated by dots
// (Not validating 0–255 ranges since you asked for 1–3 digit octets.)
const IPV4_RE = /\b(?:\d{1,3}\.){3}\d{1,3}\b/g;

const matches = s.match(IPV4_RE) || [];

const out = {};
if (matches[0]) out.ipv4_1 = matches[0];
if (matches[1]) out.ipv4_2 = matches[1];

// Put only the parsed IPv4s on msg.payload
msg.payload = out;

return msg;
